/** Deterministic Java21 oracle of input-work-bounded Java/JNI path selection. */
public final class M3LongIndexPathBudgetSelfTest {
    private static final long CANARY = 0x3a7fac8c30011abcL;
    private static long assertions;

    private M3LongIndexPathBudgetSelfTest() { }

    public static void main(String[] args) {
        boolean nativeTest = args.length == 1 && "--native".equals(args[0]);
        if (args.length > 1 || (args.length == 1 && !nativeTest)) {
            throw new IllegalArgumentException("use --native or no argument");
        }
        if (nativeTest) {
            check(M3LongIndexPathMasksJNI.nativeAvailable(), "real JNI backend required");
        } else {
            check(!M3LongIndexPathMasksJNI.nativeAvailable(),
                    "Java-only proof must run without native library");
        }
        boundaries(nativeTest);
        noProgressValidation(nativeTest);
        randomized(nativeTest);
        System.out.println("PASS M3_LONG_PATH_INPUT_BUDGET|native=" + nativeTest
                + "|assertions=" + assertions + "|rounds=2200");
    }

    private static void boundaries(boolean nativeTest) {
        long[] rows = {Long.MIN_VALUE, 17, 17, Long.MAX_VALUE, -7, -7};
        int[] offsets = {0, 1, 1, 3, 4, 0};
        int[][] planes = {{1, 0, 3, Integer.MIN_VALUE | 1, 1}};
        int[] need = {1}, forbidden = {2};
        for (M3LongIndexPathBudget.Backend backend : backends(nativeTest)) {
            long[] out = new long[5];
            Arrays.fill(out, CANARY);
            long zero = scan(rows, offsets, planes, need, forbidden,
                    0, rows.length, 1, 0, 0, out, 1, 2, backend);
            eq(0, M3LongIndexPathMasks.nextOrdinal(zero));
            eq(0, M3LongIndexPathMasks.written(zero));
            eq(new long[] {CANARY, CANARY, CANARY, CANARY, CANARY}, out);

            long budget = scan(rows, offsets, planes, need, forbidden,
                    0, rows.length, 1, 0, 2, out, 1, 2, backend);
            eq(2, M3LongIndexPathMasks.nextOrdinal(budget));
            eq(1, M3LongIndexPathMasks.written(budget));
            eq(Long.MIN_VALUE, out[1]);
            eq(CANARY, out[0]);
            eq(CANARY, out[2]);

            Arrays.fill(out, CANARY);
            long backwards = scan(rows, offsets, planes, need, forbidden,
                    rows.length - 1, rows.length, -1, 0, 3, out, 1, 2, backend);
            eq(2, M3LongIndexPathMasks.nextOrdinal(backwards));
            eq(2, M3LongIndexPathMasks.written(backwards));
            eq(new long[] {CANARY, -7, -7, CANARY, CANARY}, out);

            long stalled = scan(rows, offsets, planes, need, forbidden,
                    0, rows.length, 1, 0, 2, out, 1, 0, backend);
            eq(0, M3LongIndexPathMasks.nextOrdinal(stalled));
            eq(0, M3LongIndexPathMasks.written(stalled));
            // Validate even when no work is requested.
            fail(IllegalArgumentException.class, () -> scan(rows, new int[0], planes,
                    need, forbidden, 0, rows.length, 1, 0, 0, out, 0, 0, backend));
            fail(IllegalArgumentException.class, () -> scan(rows, offsets, planes,
                    need, forbidden, 0, rows.length, 1, 0, -1, out, 0, 0, backend));
            fail(IndexOutOfBoundsException.class, () -> scan(rows, offsets, planes,
                    need, forbidden, 0, rows.length, 1, rows.length + 1, 0,
                    out, 0, 0, backend));
            fail(IllegalArgumentException.class, () -> scan(rows, offsets, planes,
                    need, forbidden, 0, rows.length, 1, 0, 1, rows, 0, 1, backend));
            fail(IllegalArgumentException.class, () -> scan(rows, offsets, planes,
                    need, forbidden, 0, rows.length, 1, 0, 1, out, 0,
                    M3LongIndexPathMasks.MAX_WINDOW + 1, backend));
            eq(new long[] {CANARY, -7, -7, CANARY, CANARY}, out);

            // Budget preflight must not visit a bad offset beyond inspected prefix.
            int[] broken = {0, 1, 99, 3, 4, 0};
            long[] pristine = {CANARY, CANARY, CANARY};
            long prefix = scan(rows, broken, planes, new int[]{0}, new int[]{0},
                    0, rows.length, 1, 0, 2, pristine, 0, 2, backend);
            eq(2, M3LongIndexPathMasks.nextOrdinal(prefix));
            eq(2, M3LongIndexPathMasks.written(prefix));
            fail(IndexOutOfBoundsException.class, () -> scan(rows, broken, planes,
                    new int[]{0}, new int[]{0}, 0, rows.length, 1, 2, 2,
                    pristine, 0, 2, backend));
            eq(CANARY, pristine[2]);
        }
        if (!nativeTest) {
            fail(UnsatisfiedLinkError.class, () -> scan(rows, offsets, planes,
                    need, forbidden, 0, rows.length, 1, 0, 0,
                    new long[0], 0, 0, M3LongIndexPathBudget.Backend.NATIVE_REQUIRED));
        }
    }


    /** Requested output space is validated even when no input occurrence is examined. */
    private static void noProgressValidation(boolean nativeTest) {
        long[] rows = {7, 11};
        // These offsets must remain unvisited in every no-progress state.
        int[] offsets = {99, 99};
        int[][] planes = {{1}};
        int[] required = {0}, forbidden = {0};
        int[][] windows = {{0, 0, 0}, {2, 0, 0}, {2, 2, 0}, {2, 2, 1}};
        for (M3LongIndexPathBudget.Backend backend : backends(nativeTest)) {
            for (int[] window : windows) {
                int count = window[0], next = window[1], budget = window[2];
                long[] output = {CANARY, CANARY, CANARY};
                for (int limit : new int[]{-1, M3LongIndexPathMasks.MAX_WINDOW + 1}) {
                    fail(IllegalArgumentException.class, () -> scan(rows, offsets, planes,
                            required, forbidden, 0, count, 1, next, budget,
                            output, 1, limit, backend));
                    eq(new long[]{CANARY, CANARY, CANARY}, output);
                }
                fail(IndexOutOfBoundsException.class, () -> scan(rows, offsets, planes,
                        required, forbidden, 0, count, 1, next, budget,
                        output, 1, 3, backend));
                eq(new long[]{CANARY, CANARY, CANARY}, output);

                long token = scan(rows, offsets, planes, required, forbidden,
                        0, count, 1, next, budget, output, 1, 1, backend);
                eq(next, M3LongIndexPathMasks.nextOrdinal(token));
                eq(0, M3LongIndexPathMasks.written(token));
                eq(new long[]{CANARY, CANARY, CANARY}, output);

                long[] maximum = new long[M3LongIndexPathMasks.MAX_WINDOW + 2];
                Arrays.fill(maximum, CANARY);
                token = scan(rows, offsets, planes, required, forbidden,
                        0, count, 1, next, budget, maximum, 1,
                        M3LongIndexPathMasks.MAX_WINDOW, backend);
                eq(next, M3LongIndexPathMasks.nextOrdinal(token));
                eq(0, M3LongIndexPathMasks.written(token));
                for (long value : maximum) eq(CANARY, value);
            }
        }
        if (!nativeTest) {
            fail(UnsatisfiedLinkError.class, () -> scan(rows, offsets, planes,
                    required, forbidden, 0, 2, 1, 0, 0, new long[1], 0, -1,
                    M3LongIndexPathBudget.Backend.NATIVE_REQUIRED));
        }
    }

    private static void randomized(boolean nativeTest) {
        Random random = new Random(0x4d33534f52544544L);
        M3LongIndexPathBudget.Backend[] backends = backends(nativeTest);
        for (int round = 0; round < 2200; round++) {
            int length = random.nextInt(110);
            int capacity = random.nextInt(90) + 1;
            int stages = random.nextInt(4) + 1;
            long[] rows = new long[length];
            int[] positions = new int[length];
            int[][] states = new int[stages][capacity];
            int[] need = new int[stages], forbid = new int[stages];
            for (int i = 0; i < length; i++) {
                rows[i] = switch (i % 11) {
                    case 0 -> Long.MIN_VALUE;
                    case 1 -> Long.MAX_VALUE;
                    default -> random.nextLong(21) - 10;
                };
                positions[i] = random.nextInt(capacity);
            }
            for (int s = 0; s < stages; s++) {
                for (int i = 0; i < capacity; i++) states[s][i] = random.nextInt();
                switch (round % 7) {
                    case 0 -> { need[s] = 0; forbid[s] = 0; }
                    case 1 -> { need[s] = Integer.MIN_VALUE; forbid[s] = 0; }
                    case 2 -> { need[s] = -1; forbid[s] = -1; }
                    case 3 -> { need[s] = 1; forbid[s] = 2; }
                    case 4 -> { need[s] = 0; forbid[s] = Integer.MIN_VALUE; }
                    case 5 -> {
                        int sample = length == 0 ? states[s][0] : states[s][positions[0]];
                        need[s] = sample & 0x81000001;
                        forbid[s] = ~sample & 0x04000002;
                    }
                    default -> { need[s] = random.nextInt(8); forbid[s] = 16 * random.nextInt(8); }
                }
            }
            int first = length == 0 ? 0 : random.nextInt(length);
            int stride = (random.nextBoolean() ? 1 : -1) * (random.nextInt(4) + 1);
            int maximum = length == 0 ? 0
                    : (stride > 0 ? (length - 1 - first) / stride : first / -stride) + 1;
            int count = random.nextInt(maximum + 1);
            long[] expected = M3LongIndexPathMasks.select(rows, positions, states,
                    need, forbid, first, count, stride);
            int limit = random.nextInt(8) + 1;
            int maxExamined = random.nextInt(15) + 1;
            long[] javaPages = collect(rows, positions, states, need, forbid,
                    first, count, stride, limit, maxExamined,
                    M3LongIndexPathBudget.Backend.JAVA);
            eq(expected, javaPages);
            if (nativeTest) {
                long[] nativePages = collect(rows, positions, states, need, forbid,
                        first, count, stride, limit, maxExamined,
                        M3LongIndexPathBudget.Backend.NATIVE_REQUIRED);
                eq(javaPages, nativePages);
            }
        }
    }

    private static long[] collect(long[] rows, int[] positions, int[][] states,
            int[] need, int[] forbid, int first, int count, int stride,
            int limit, int maxExamined, M3LongIndexPathBudget.Backend backend) {
        ArrayList<Long> output = new ArrayList<>(); // oracle-only, never production.
        long[] page = new long[limit + 2];
        int next = 0;
        while (next < count) {
            Arrays.fill(page, CANARY);
            long token = scan(rows, positions, states, need, forbid, first, count,
                    stride, next, maxExamined, page, 1, limit, backend);
            int advanced = M3LongIndexPathMasks.nextOrdinal(token);
            int written = M3LongIndexPathMasks.written(token);
            check(advanced > next && advanced <= count, "nonterminal page must advance");
            check(advanced - next <= maxExamined, "input work budget exceeded");
            check(written >= 0 && written <= limit, "output limit exceeded");
            eq(CANARY, page[0]);
            eq(CANARY, page[page.length - 1]);
            for (int i = 0; i < written; i++) output.add(page[1 + i]);
            next = advanced;
        }
        return output.stream().mapToLong(Long::longValue).toArray();
    }

    private static long scan(long[] rows, int[] offsets, int[][] planes,
            int[] required, int[] forbidden, int first, int count, int stride,
            int next, int budget, long[] output, int offset, int limit,
            M3LongIndexPathBudget.Backend backend) {
        return M3LongIndexPathBudget.scan(rows, offsets, planes,
                required, forbidden, first, count, stride, next, budget,
                output, offset, limit, backend);
    }

    private static M3LongIndexPathBudget.Backend[] backends(boolean nativeTest) {
        return nativeTest
                ? new M3LongIndexPathBudget.Backend[]{M3LongIndexPathBudget.Backend.JAVA,
                        M3LongIndexPathBudget.Backend.NATIVE_REQUIRED}
                : new M3LongIndexPathBudget.Backend[]{M3LongIndexPathBudget.Backend.JAVA};
    }

    private static void check(boolean condition, String message) {
        assertions++;
        if (!condition) throw new AssertionError(message);
    }
    private static void eq(long expected, long actual) {
        check(expected == actual, "expected " + expected + " got " + actual);
    }
    private static void eq(long[] expected, long[] actual) {
        check(Arrays.equals(expected, actual),
                "expected " + Arrays.toString(expected) + " got " + Arrays.toString(actual));
    }
    private static void fail(Class<? extends Throwable> type, Runnable action) {
        assertions++;
        try { action.run(); }
        catch (Throwable actual) {
            if (type.isInstance(actual)) return;
            throw new AssertionError("wrong exception: " + actual, actual);
        }
        throw new AssertionError("expected " + type.getName());
    }
}
